const catalogs: Record<string, Record<string, string>> = { zh, ja, ko, es, fr }
const explicitCatalogKeys: Readonly<Record<string, ReadonlySet<string>>> = Object.fromEntries(
  Object.entries(catalogs).map(([language, catalog]) => [language, new Set(Object.keys(catalog))]),
)

for (const catalog of [ja, ko, es, fr]) {
  for (const key of Object.keys(zh)) {
    if (!(key in catalog)) catalog[key] = key
  }
}

export function hasExplicitTranslation(language: DoCodeLanguage, value: string) {
  return explicitCatalogKeys[language]?.has(value) ?? false
}

export function t(language: DoCodeLanguage, value: string, values: Record<string, string | number> = {}) {
  return (catalogs[language]?.[value] ?? value)
    .replace("[zh|en]", "[en|zh|ja|ko|es|fr]")
    .replace(/\{(\w+)\}/g, (_, key: string) => String(values[key] ?? `{${key}}`))
}

export function languageDisplay(language: DoCodeLanguage, locale: DoCodeLanguage = language) {
  const definition = localeDefinition(language)
  return `${t(locale, definition.englishName)} [${definition.bcp47}]`
}

export function availableLanguagesText(locale: DoCodeLanguage) {
  return localeDefinitions.map((language) => languageDisplay(language.id, locale)).join(", ")
}

export function languageUsageText() {
  return `/language [${localeDefinitions.map((language) => language.id).join("|")}]`
}

export function invalidLanguageText(locale: DoCodeLanguage) {
  return `${t(locale, "Invalid language. Usage")}: ${languageUsageText()}`
}
